//! Acceptance 3: `share-usage` keeps the Python summary, per-request page,
//! filters, cursor and coverage semantics.
//!
//! The expected bodies come from `tests/fixtures/rust_console_reads_rev1.json`,
//! generated by `tests/generate_rust_console_reads_fixture.py` from the real
//! Python cloud `usagesrv.Handler`, `share/metering.py` and `share/store.py`.
//! Window filters run against a fixed read instant so the fixture is stable;
//! the HTTP cases pin only time-independent bodies and status codes.

mod support;

use serde_json::{json, Value};

use support::*;
use um_console::metering::{self, UsageFilters};

const NOW: f64 = 1_700_000_000.0;

fn start_usage_console(temp: &um_test_harness::TempDataDir, fixture: &Value) -> Console {
    let backend = temp.path().join("share-backend");
    std::fs::create_dir_all(&backend).expect("backend dir");
    std::fs::write(
        backend.join("usage-share-backend.jsonl"),
        fixture["shareUsage"]["ledger"].as_str().expect("ledger"),
    )
    .expect("write ledger");
    start_console_with_seams(
        temp,
        |config| {
            config.share_store_file = Some(temp.path().join("share.db"));
            config.share_backend_dir = Some(backend.clone());
        },
        std::sync::Arc::new(StaticShareSeams::new()),
    )
}

fn remove_checked_at(body: &mut Value) {
    if let Some(object) = body.as_object_mut() {
        object.remove("checkedAt");
    }
}

fn write_ledger(temp: &um_test_harness::TempDataDir, fixture: &Value) -> std::path::PathBuf {
    let backend = temp.path().join("share-backend");
    std::fs::create_dir_all(&backend).expect("backend dir");
    let ledger = backend.join("usage-share-backend.jsonl");
    std::fs::write(
        &ledger,
        fixture["shareUsage"]["ledger"].as_str().expect("ledger"),
    )
    .expect("write ledger");
    ledger
}

fn summary_case(ledger: &std::path::Path, store: &std::path::Path, filter: UsageFilters) -> Value {
    let mut body =
        metering::usage_summary_for_tests(ledger, &filter, 200_000, Some(NOW)).expect("summary");
    metering::attach_key_labels(&mut body, "keys", "key_id", Some(&store.to_path_buf()));
    remove_checked_at(&mut body);
    body
}

fn requests_case(
    ledger: &std::path::Path,
    store: &std::path::Path,
    filter: UsageFilters,
    cursor: Option<&str>,
    limit: i64,
) -> Value {
    let mut body = metering::usage_requests_for_tests(ledger, &filter, cursor, limit, Some(NOW))
        .expect("requests");
    metering::attach_key_labels(&mut body, "rows", "keyId", Some(&store.to_path_buf()));
    remove_checked_at(&mut body);
    body
}

fn filters(
    window: Option<&str>,
    key_id: Option<&str>,
    model: Option<&str>,
    result: Option<&str>,
) -> UsageFilters {
    UsageFilters {
        window: window.map(str::to_string),
        key_id: key_id.map(str::to_string),
        model: model.map(str::to_string),
        result: result.map(str::to_string),
    }
}

#[test]
fn summary_matches_every_python_filter_and_coverage_case() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let ledger = write_ledger(&temp, &fixture);
    let store = temp.path().join("share.db");
    let cases = fixture["shareUsage"]["summary"].as_object().expect("cases");
    let actual = [
        ("all", filters(None, None, None, None)),
        ("window7d", filters(Some("7d"), None, None, None)),
        ("window24h", filters(Some("24h"), None, None, None)),
        ("window1h", filters(Some("1h"), None, None, None)),
        (
            "unattributed",
            filters(None, Some("unattributed"), None, None),
        ),
        ("keyActive", filters(None, Some("key-active-1"), None, None)),
        ("modelGpt", filters(None, None, Some("gpt-4o"), None)),
        (
            "resultCancelled",
            filters(None, None, None, Some("cancelled")),
        ),
        (
            "combined",
            filters(Some("7d"), None, Some("gpt-4o"), Some("success")),
        ),
    ];
    for (name, filter) in actual {
        assert_eq!(summary_case(&ledger, &store, filter), cases[name], "{name}");
    }
}

#[test]
fn requests_page_keeps_cursor_filters_and_coverage() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let ledger = write_ledger(&temp, &fixture);
    let store = temp.path().join("share.db");
    let cases = fixture["shareUsage"]["requests"]
        .as_object()
        .expect("cases");
    let default = requests_case(&ledger, &store, filters(None, None, None, None), None, 50);
    assert_eq!(default, cases["default"]);
    let limit2 = requests_case(&ledger, &store, filters(None, None, None, None), None, 2);
    assert_eq!(limit2, cases["limit2"]);
    let cursor = limit2["nextCursor"].as_str().expect("cursor");
    assert_eq!(
        requests_case(
            &ledger,
            &store,
            filters(None, None, None, None),
            Some(cursor),
            2,
        ),
        cases["cursor"]
    );
    assert_eq!(
        requests_case(
            &ledger,
            &store,
            filters(Some("7d"), None, Some("gpt-4o"), Some("success")),
            None,
            50,
        ),
        cases["filtered"]
    );
    assert_eq!(
        requests_case(
            &ledger,
            &store,
            filters(None, Some("no-such-key"), None, None),
            None,
            50,
        ),
        cases["unknownKey"]
    );
}

#[test]
fn http_cases_match_python_status_and_time_independent_bodies() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let console = start_usage_console(&temp, &fixture);
    let cases = fixture["shareUsage"]["http"].as_object().expect("cases");
    let targets = [
        ("all", "/api/console/share-usage".to_string()),
        (
            "invalidWindow",
            "/api/console/share-usage?window=2d".to_string(),
        ),
        (
            "invalidResult",
            "/api/console/share-usage?result=bogus".to_string(),
        ),
        (
            "duplicateWindow",
            "/api/console/share-usage?window=1h&window=7d".to_string(),
        ),
        (
            "unknownQuery",
            "/api/console/share-usage?bogus=1".to_string(),
        ),
        (
            "requestsDefault",
            "/api/console/share-usage/requests".to_string(),
        ),
        (
            "requestsLimit2",
            "/api/console/share-usage/requests?limit=2".to_string(),
        ),
        (
            "requestsInvalidLimitZero",
            "/api/console/share-usage/requests?limit=0".to_string(),
        ),
        (
            "requestsInvalidLimitText",
            "/api/console/share-usage/requests?limit=abc".to_string(),
        ),
        (
            "requestsInvalidCursor",
            "/api/console/share-usage/requests?cursor=abc".to_string(),
        ),
        (
            "requestsUnknownKey",
            "/api/console/share-usage/requests?key=no-such-key".to_string(),
        ),
    ];
    for (name, target) in targets {
        let expected = &cases[name];
        let response = client_request(console.addr, &ClientRequest::get(&target)).expect("request");
        let mut body = response.json();
        remove_checked_at(&mut body);
        assert_eq!(
            u64::from(response.status),
            expected["status"].as_u64().unwrap(),
            "{name}"
        );
        assert_eq!(body, expected["body"], "{name}");
        assert_eq!(
            response.header("cache-control"),
            expected["cacheControl"].as_str(),
            "{name}"
        );
    }
}

#[test]
fn summary_never_folds_unknown_usage_or_missing_key_names_into_zero() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let ledger = write_ledger(&temp, &fixture);
    let store = temp.path().join("share.db");
    let body = summary_case(&ledger, &store, filters(None, None, None, None));
    assert_eq!(
        body["coverage"]["keyNames"],
        json!(3),
        "labels are read only for the key ids present in the rows"
    );
    assert_eq!(body["coverage"]["unknownUsageRequests"], json!(1));
    assert_eq!(body["coverage"]["attributionReasons"], json!({"absent": 1}));
    let unattributed = &body["unattributed"];
    assert_eq!(unattributed["unknownRequests"], json!(1));
    assert_eq!(unattributed["tokenUsage"]["unknownRequests"], json!(1));
    assert_eq!(unattributed["tokenUsage"]["completeRequests"], json!(0));
    assert_eq!(unattributed["tokenUsage"]["totalTokens"], json!(null));
}

#[test]
fn summary_refuses_the_private_ledger() {
    let temp = temp();
    let private_path = temp.path().join("usage-chat2api.jsonl");
    std::fs::write(&private_path, "{\"requests\":1}\n").expect("private ledger");
    let error =
        metering::usage_summary_for_tests(&private_path, &UsageFilters::default(), 200_000, None)
            .expect_err("private ledger");
    assert!(error
        .0
        .contains("refusing to read the private chat2api ledger"));
}

#[test]
fn missing_backend_dir_is_an_honest_503_not_an_empty_page() {
    let temp = temp();
    let console = start_console_with_seams(
        &temp,
        |config| {
            config.share_store_file = Some(temp.path().join("share.db"));
            config.share_backend_dir = None;
        },
        std::sync::Arc::new(StaticShareSeams::new()),
    );
    let response = client_request(
        console.addr,
        &ClientRequest::get("/api/console/share-usage"),
    )
    .expect("request");
    assert_eq!(response.status, 503);
    assert_eq!(
        response.json(),
        json!({"error": "share_ledger_path_unresolved"})
    );
}

#[test]
fn ledger_path_is_never_returned_in_a_response() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let console = start_usage_console(&temp, &fixture);
    let response = client_request(
        console.addr,
        &ClientRequest::get("/api/console/share-usage"),
    )
    .expect("request");
    let body = String::from_utf8_lossy(&response.body);
    let absolute = temp.path().to_string_lossy().to_string();
    assert!(!body.contains(&absolute), "absolute ledger dir leaked");
    assert!(body.contains("usage-share-backend.jsonl"));
}
